import{_ as p,a0 as l,w as o,s as r,ao as u,I as a,x as i,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何為 Linux 虛擬控制台配置鼠標支持 | LCTT x X-CMD","titleTemplate":false,"description":"如何為 Linux 虛擬控制台配置鼠標支持 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何為 Linux 虛擬控制台配置鼠標支持 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何為 Linux 虛擬控制台配置鼠標支持 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180912 How To Configure Mouse Support For Linux Virtual Consoles","title":"如何為 Linux 虛擬控制台配置鼠標支持","tag":"201809","desc":""},"relativePath":"201809/20180912 How To Configure Mouse Support For Linux Virtual Consoles.md","filePath":"[post].md"}'),d={name:"201809/20180912 How To Configure Mouse Support For Linux Virtual Consoles.md"};function g(h,s,c,b,k,m){const n=l("Link");return o(),r("div",null,[s[15]||(s[15]=u(`<h1 id="如何為-linux-虛擬控制台配置鼠標支持" tabindex="-1">如何為 Linux 虛擬控制台配置鼠標支持 <a class="header-anchor" href="#如何為-linux-虛擬控制台配置鼠標支持" aria-label="Permalink to “如何為 Linux 虛擬控制台配置鼠標支持”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/GPM-1-720x340.png" alt=""></p><p>我使用 Oracle VirtualBox 來測試各種類 Unix 操作系統。我的大多數虛擬機都是<ruby>無頭<rt>headless</rt></ruby>服務器，它們沒有圖形桌面環境。很長一段時間，我一直想知道如何在無頭 Linux 服務器的基於文本的終端中使用鼠標。感謝 <strong>GPM</strong>，今天我瞭解到我們可以在虛擬控制台中使用鼠標進行復制和粘貼操作。 <strong>GPM</strong>，是<ruby>通用鼠標<rt>General Purpose Mouse</rt></ruby>的首字母縮寫，它是一個守護程序，可以幫助你配置 Linux 虛擬控制台的鼠標支持。請不要將 GPM 與 <strong>GDM</strong>（<ruby>GNOME 顯示管理器<rt>GNOME Display manager</rt></ruby>）混淆。兩者有完全不同的用途。</p><p>GPM 在以下場景中特別有用：</p><ul><li>新的 Linux 服務器安裝或默認情況下不能或不使用 X Windows 的系統，如 Arch Linux 和 Gentoo。</li><li>在虛擬終端/控制台中使用複製/粘貼操作。</li><li>在基於文本的編輯器和瀏覽器中使用複製/粘貼（例如，emacs、lynx）。</li><li>在文本文件管理器中使用複製/粘貼（例如 Ranger、Midnight commander）。</li></ul><p>在這個簡短的教程中，我們將看到如何在類 Unix 操作系統中在基於文本的終端中使用鼠標。</p><h3 id="安裝-gpm" tabindex="-1">安裝 GPM <a class="header-anchor" href="#安裝-gpm" aria-label="Permalink to “安裝 GPM”">​</a></h3><p>要在純文本 Linux 系統中啓用鼠標支持，請安裝 GPM 包。它在大多數 Linux 發行版的默認倉庫中都有。</p><p>在 Arch Linux 及其變體如 Antergos、Manjaro Linux 上，運行以下命令來安裝 GPM：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S gpm</span></span></code></pre></div><p>在 Debian、Ubuntu、Linux Mint 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install gpm</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install gpm</span></span></code></pre></div><p>在 openSUSE 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo zypper install gpm</span></span></code></pre></div><p>安裝後，使用以下命令啓用並啓動 GPM 服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable gpm</span></span>
<span class="line"><span>$ sudo systemctl start gpm</span></span></code></pre></div><p>在基於 Debian 的系統中，gpm 服務將在你安裝後自動啓動，因此你無需如上所示手動啓動服務。</p><h3 id="為-linux-虛擬控制台配置鼠標支持" tabindex="-1">為 Linux 虛擬控制台配置鼠標支持 <a class="header-anchor" href="#為-linux-虛擬控制台配置鼠標支持" aria-label="Permalink to “為 Linux 虛擬控制台配置鼠標支持”">​</a></h3><p>無需特殊配置。GPM 將在你安裝並啓動 gpm 服務後立即開始工作。</p><p>在安裝 GPM 之前，看下我的 Ubuntu 18.04 LTS 服務器的屏幕截圖：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/Ubuntu-18.04-CLI.png" alt=""></p><p>正如你在上面的截圖中看到的，我的 Ubuntu 18.04 LTS 無頭服務器中沒有可見的鼠標指針。只有一個閃爍的光標，它不能讓我選擇文本，使用鼠標複製/粘貼文本。在僅限 CLI 的 Linux 服務器中，鼠標根本沒用。</p><p>在安裝 GPM 後查看 Ubuntu 18.04 LTS 服務器的以下截圖：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/GPM.png" alt=""></p><p>看見了嗎？我現在可以選擇文字了。</p><p>要選擇，複製和粘貼文本，請執行以下操作：</p><ul><li>要選擇文本，請按下鼠標左鍵並拖動鼠標。</li><li>選擇文本後，放開鼠標左鍵，並按下中鍵在同一個或另一個控制台中粘貼文本。</li><li>右鍵用於擴展選擇，就像在 <code>xterm</code> 中。</li><li>如果你使用的是雙鍵鼠標，請使用右鍵粘貼文本。</li></ul><p>就這麼簡單！</p><p>就像我已經説過的那樣，GPM 工作得很好，並且不需要額外的配置。以下是 GPM 配置文件 <code>/etc/gpm.conf</code>（或在某些發行版中是 <code>/etc/conf.d/gpm</code>）的示例內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># protected from evaluation (i.e. by quoting them).</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># This file is used by /etc/init.d/gpm and can be modified by</span></span>
<span class="line"><span># &quot;dpkg-reconfigure gpm&quot; or by hand at your option.</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span>device=/dev/input/mice</span></span>
<span class="line"><span>responsiveness=</span></span>
<span class="line"><span>repeat_type=none</span></span>
<span class="line"><span>type=exps2</span></span>
<span class="line"><span>append=&#39;&#39;</span></span>
<span class="line"><span>sample_rate=</span></span></code></pre></div><p>在我的例子中，我使用 USB 鼠標。如果你使用的是其他鼠標，則可能需要更改 <code>device=/dev/input/mice</code> 和 <code>type=exps2</code> 參數的值。</p><p>有關更多詳細信息，請參閲手冊頁。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man gpm</span></span></code></pre></div><p>就是這些了。希望這個有用。還有更多的好東西。敬請期待！</p><p>乾杯!</p><hr>`,38)),a("p",null,[s[1]||(s[1]=i("via: ",-1)),e(n,{href:"https://www.ostechnix.com/how-to-configure-mouse-support-for-linux-virtual-consoles/"},{default:t(()=>[...s[0]||(s[0]=[i("https://www.ostechnix.com/how-to-configure-mouse-support-for-linux-virtual-consoles/",-1)])]),_:1})]),a("p",null,[s[6]||(s[6]=i("作者：",-1)),e(n,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[2]||(s[2]=[i("SK",-1)])]),_:1}),s[7]||(s[7]=i(" \u2028選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[8]||(s[8]=i(" \u2028譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[i("geekpi",-1)])]),_:1}),s[9]||(s[9]=i(" \u2028校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),a("p",null,[s[12]||(s[12]=i("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[i("Linux中國",-1)])]),_:1}),s[14]||(s[14]=i(" 榮譽推出",-1))])])}const C=p(d,[["render",g]]);export{y as __pageData,C as default};
